import React, { useState } from "react";
import { createClient } from "@supabase/supabase-js";
import { User, Briefcase, FileText, Edit3, ImagePlus, X, Plus, Calendar, Instagram, Music2, ChevronLeft, ChevronRight, Eye, Mail } from "lucide-react";

const C = {
  black: "#0A0A0A",
  charcoal: "#2B2B28",
  ash: "#9C9890",
  ivory: "#FAF7F2",
  stone: "#E6E2DC",
};

const LOGO = "data:image/png;base64,";

const supabaseUrl = "https://zngodembjlncpuvkoazc.supabase.co";
const supabaseKey = "sb_publishable_JADnZ6dBDAE3Hb4AhSO_mA_av-6NPJi";
const supabase = createClient(supabaseUrl, supabaseKey);

export default function FichaCliente() {
  const [fechaIngreso, setFechaIngreso] = useState("");
  const [nombre, setNombre] = useState("");
  const [correo, setCorreo] = useState("");
  const [profesion, setProfesion] = useState("");
  const [dedicacion, setDedicacion] = useState("");
  const [monetiza, setMonetiza] = useState(null);
  const [instagram, setInstagram] = useState("");
  const [tiktok, setTiktok] = useState("");
  const [tono, setTono] = useState("");
  const [notas, setNotas] = useState("");
  const [capturaIG, setCapturaIG] = useState(null);

  const [referencias, setReferencias] = useState([]);
  const [indiceRef, setIndiceRef] = useState(0);
  const [notasReferencias, setNotasReferencias] = useState("");
  const [visualizacion, setVisualizacion] = useState("");

  const [guardando, setGuardando] = useState(false);
  const [guardado, setGuardado] = useState(false);
  const [errorGuardar, setErrorGuardar] = useState("");
  const [linkFicha, setLinkFicha] = useState("");

  const handleGuardar = async () => {
    setGuardando(true);
    setGuardado(false);
    setErrorGuardar("");
    setLinkFicha("");
    const { data, error } = await supabase
      .from("fichas_clientes")
      .insert([
        {
          fecha_ingreso: fechaIngreso || null,
          nombre,
          correo,
          profesion,
          dedicacion,
          monetiza,
          tono,
          instagram,
          tiktok,
          notas,
          captura_ig: capturaIG,
          referencias,
          notas_referencias: notasReferencias,
          visualizacion,
        },
      ])
      .select("id")
      .single();
    setGuardando(false);
    if (error) {
      setErrorGuardar("No se pudo guardar: " + error.message);
    } else {
      setGuardado(true);
      const url = `${window.location.origin}/ficha?id=${data.id}`;
      setLinkFicha(url);
    }
  };

  const copiarLink = () => {
    navigator.clipboard.writeText(linkFicha);
  };

  const compressImage = (file, maxWidth = 900, quality = 0.7) =>
    new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const img = new Image();
        img.onload = () => {
          const scale = Math.min(1, maxWidth / img.width);
          const canvas = document.createElement("canvas");
          canvas.width = img.width * scale;
          canvas.height = img.height * scale;
          const ctx = canvas.getContext("2d");
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
          resolve(canvas.toDataURL("image/jpeg", quality));
        };
        img.src = ev.target.result;
      };
      reader.readAsDataURL(file);
    });

  const handleImage = (setter) => async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const compressed = await compressImage(file);
    setter(compressed);
  };

  const handleReferencias = async (e) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;
    const nuevas = await Promise.all(files.map((file) => compressImage(file, 700, 0.6)));
    setReferencias((prev) => [...prev, ...nuevas]);
  };

  const eliminarReferencia = (idx) => {
    setReferencias((prev) => prev.filter((_, i) => i !== idx));
    setIndiceRef(0);
  };

  return (
    <div style={{ minHeight: "100vh", background: C.ivory, color: C.black, fontFamily: "\'Montserrat\', sans-serif", boxSizing: "border-box" }}>
      <style>{`
        * { box-sizing: border-box; }
        @import url(\'https://fonts.googleapis.com/css2?family=Prata&family=Montserrat:wght@400;500;600;700&display=swap\');
        .prata { font-family: \'Prata\', serif; }
        input, textarea {
          font-family: \'Montserrat\', sans-serif;
          border: none;
          background: transparent;
          padding: 0;
          font-size: 15px;
          color: ${C.black};
          outline: none;
          width: 100%;
        }
        textarea { resize: none; line-height: 1.5; }
        ::placeholder { color: ${C.ash}; }
        input[type="date"] { color: ${C.black}; }
        input[type="date"]::-webkit-calendar-picker-indicator { opacity: 0.6; cursor: pointer; }
        .card {
          background: #fff;
          border-radius: 22px;
          box-shadow: 0 10px 30px rgba(10,10,10,0.06);
          padding: 4px 22px;
          margin-bottom: 22px;
        }
        .row {
          display: flex;
          align-items: flex-start;
          gap: 14px;
          padding: 18px 0;
          border-bottom: 1px solid ${C.stone};
        }
        .row:last-child { border-bottom: none; }
        .row-icon {
          width: 36px;
          height: 36px;
          min-width: 36px;
          border-radius: 50%;
          background: ${C.ivory};
          border: 1px solid ${C.stone};
          display: flex;
          align-items: center;
          justify-content: center;
          color: ${C.charcoal};
          margin-top: 2px;
        }
        .row-content { flex: 1; min-width: 0; }
        .row-label {
          font-size: 11px;
          letter-spacing: 0.03em;
          color: ${C.ash};
          margin-bottom: 4px;
        }
        .ficha-grid {
          display: grid;
          grid-template-columns: 1.4fr 1fr;
          gap: 40px;
          align-items: start;
        }
        @media (max-width: 640px) {
          .ficha-grid { grid-template-columns: 1fr; }
        }
        .ref-heading {
          font-size: 21px;
          margin: 0 0 4px;
        }
        .ref-subheading {
          font-size: 13.5px;
          color: ${C.charcoal};
          margin: 0 0 20px;
        }
      `}</style>

      <div style={{ maxWidth: 920, margin: "0 auto", padding: "36px 32px 80px" }}>
        {/* HEADER */}
        <div style={{ textAlign: "center", marginBottom: 40 }}>
          <img src={LOGO} alt="BUILT" style={{ height: 78, display: "inline-block" }} />
        </div>

        <div
          className="prata"
          style={{
            display: "inline-block",
            background: C.black,
            color: C.ivory,
            padding: "12px 28px",
            borderRadius: 999,
            fontSize: 22,
            margin: "0 0 32px",
          }}
        >
          Ficha de ingreso
        </div>

        {/* CUERPO: DOS COLUMNAS */}
        <div className="ficha-grid">
          <div style={{ minWidth: 0 }}>
            {/* TARJETA: DATOS */}
            <div className="card">
              <div className="row">
                <div className="row-icon"><Calendar size={16} /></div>
                <div className="row-content">
                  <div className="row-label">Fecha de ingreso</div>
                  <input
                    type="date"
                    value={fechaIngreso}
                    onChange={(e) => setFechaIngreso(e.target.value)}
                  />
                </div>
              </div>
              <div className="row">
                <div className="row-icon"><User size={16} /></div>
                <div className="row-content">
                  <div className="row-label">Nombre completo</div>
                  <input
                    value={nombre}
                    onChange={(e) => setNombre(e.target.value)}
                    placeholder="Escribe el nombre"
                  />
                </div>
              </div>
              <div className="row">
                <div className="row-icon"><Mail size={16} /></div>
                <div className="row-content">
                  <div className="row-label">Correo</div>
                  <input
                    type="email"
                    value={correo}
                    onChange={(e) => setCorreo(e.target.value)}
                    placeholder="correo@ejemplo.com"
                  />
                </div>
              </div>
              <div className="row">
                <div className="row-icon"><Briefcase size={16} /></div>
                <div className="row-content">
                  <div className="row-label">Profesión</div>
                  <input
                    value={profesion}
                    onChange={(e) => setProfesion(e.target.value)}
                    placeholder="Escribe la profesión"
                  />
                </div>
              </div>
              <div className="row">
                <div className="row-icon"><FileText size={16} /></div>
                <div className="row-content">
                  <div className="row-label">¿A qué se dedica?</div>
                  <textarea
                    rows={2}
                    value={dedicacion}
                    onChange={(e) => setDedicacion(e.target.value)}
                    placeholder="Describe brevemente"
                  />
                </div>
              </div>
            </div>

            {/* TARJETA: REDES */}
            <div className="card">
              <div className="row">
                <div className="row-icon"><Eye size={16} /></div>
                <div className="row-content">
                  <div className="row-label">¿Cómo te gustaría que te perciban?</div>
                  <textarea
                    rows={2}
                    value={tono}
                    onChange={(e) => setTono(e.target.value)}
                    placeholder="Describe el tono que quieres comunicar"
                  />
                </div>
              </div>
              <div className="row">
                <div className="row-icon"><Instagram size={16} /></div>
                <div className="row-content">
                  <div className="row-label">Instagram</div>
                  <input
                    value={instagram}
                    onChange={(e) => setInstagram(e.target.value)}
                    placeholder="@usuario"
                  />
                </div>
              </div>
              <div className="row">
                <div className="row-icon"><Music2 size={16} /></div>
                <div className="row-content">
                  <div className="row-label">TikTok</div>
                  <input
                    value={tiktok}
                    onChange={(e) => setTiktok(e.target.value)}
                    placeholder="@usuario"
                  />
                </div>
              </div>
            </div>

            {/* TARJETA: MONETIZACIÓN + NOTAS */}
            <div className="card">
              <div className="row">
                <div className="row-icon">$</div>
                <div className="row-content">
                  <div className="row-label">¿Monetiza sus conocimientos?</div>
                  <div style={{ display: "flex", gap: 10, marginTop: 6 }}>
                    <Pill active={monetiza === true} onClick={() => setMonetiza(true)}>Sí</Pill>
                    <Pill active={monetiza === false} onClick={() => setMonetiza(false)}>No</Pill>
                  </div>
                </div>
              </div>
              <div className="row">
                <div className="row-icon"><Edit3 size={16} /></div>
                <div className="row-content">
                  <div className="row-label">Notas</div>
                  <textarea
                    rows={3}
                    value={notas}
                    onChange={(e) => setNotas(e.target.value)}
                    placeholder="Información adicional"
                  />
                </div>
              </div>
            </div>
          </div>

          <div style={{ minWidth: 0 }}>
            <PhoneFrame image={capturaIG} onChange={handleImage(setCapturaIG)} onClear={() => setCapturaIG(null)} />
          </div>
        </div>

        {/* CARRUSEL DE REFERENCIAS */}
        <div style={{ marginTop: 56, borderTop: `1px solid ${C.stone}`, paddingTop: 40 }}>
          <h2 className="prata ref-heading">Referencias visuales</h2>
          <div
            className="prata"
            style={{
              display: "inline-block",
              background: C.black,
              color: C.ivory,
              padding: "8px 20px",
              borderRadius: 999,
              fontSize: 14,
              margin: "0 0 20px",
            }}
          >
            ¿Cómo te gustaría verte?
          </div>

          {referencias.length === 0 ? (
            <label
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                gap: 12,
                border: `1.5px dashed ${C.stone}`,
                borderRadius: 18,
                padding: "56px 20px",
                cursor: "pointer",
                color: C.ash,
                fontSize: 13.5,
                background: "#FFFEFC",
                maxWidth: 520,
              }}
            >
              <div
                style={{
                  width: 44,
                  height: 44,
                  borderRadius: "50%",
                  background: C.ivory,
                  border: `1px solid ${C.stone}`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <ImagePlus size={19} color={C.charcoal} />
              </div>
              Subir imágenes de referencia
              <input type="file" accept="image/*" multiple onChange={handleReferencias} style={{ display: "none" }} />
            </label>
          ) : (
            <div style={{ maxWidth: 520 }}>
              <div
                style={{
                  position: "relative",
                  borderRadius: 18,
                  overflow: "hidden",
                  background: C.stone,
                  aspectRatio: "4/5",
                  boxShadow: "0 12px 32px rgba(10,10,10,0.10)",
                }}
              >
                <img
                  src={referencias[indiceRef]}
                  alt={`referencia ${indiceRef + 1}`}
                  style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
                />

                <div
                  style={{
                    position: "absolute",
                    top: 14,
                    left: 14,
                    background: "rgba(10,10,10,0.55)",
                    color: C.ivory,
                    fontSize: 11.5,
                    padding: "5px 12px",
                    borderRadius: 999,
                    letterSpacing: "0.04em",
                  }}
                >
                  {indiceRef + 1} / {referencias.length}
                </div>

                <button
                  onClick={() => eliminarReferencia(indiceRef)}
                  style={{
                    position: "absolute",
                    top: 12,
                    right: 12,
                    background: "rgba(10,10,10,0.55)",
                    border: "none",
                    borderRadius: "50%",
                    width: 28,
                    height: 28,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    cursor: "pointer",
                  }}
                >
                  <X size={13} color={C.ivory} />
                </button>

                {referencias.length > 1 && (
                  <>
                    <button
                      onClick={() => setIndiceRef((i) => (i - 1 + referencias.length) % referencias.length)}
                      style={navArrowStyle("left")}
                    >
                      <ChevronLeft size={18} color={C.black} />
                    </button>
                    <button
                      onClick={() => setIndiceRef((i) => (i + 1) % referencias.length)}
                      style={navArrowStyle("right")}
                    >
                      <ChevronRight size={18} color={C.black} />
                    </button>
                  </>
                )}
              </div>

              {/* TIRA DE MINIATURAS */}
              <div style={{ display: "flex", gap: 8, marginTop: 14, overflowX: "auto", paddingBottom: 4 }}>
                {referencias.map((src, i) => (
                  <div
                    key={i}
                    onClick={() => setIndiceRef(i)}
                    style={{
                      width: 52,
                      height: 52,
                      borderRadius: 10,
                      overflow: "hidden",
                      flexShrink: 0,
                      cursor: "pointer",
                      border: i === indiceRef ? `2px solid ${C.black}` : `2px solid transparent`,
                      opacity: i === indiceRef ? 1 : 0.55,
                      transition: "opacity 0.15s ease",
                    }}
                  >
                    <img src={src} alt={`mini ${i + 1}`} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
                  </div>
                ))}
                <label
                  style={{
                    width: 52,
                    height: 52,
                    borderRadius: 10,
                    border: `1.5px dashed ${C.stone}`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    cursor: "pointer",
                    flexShrink: 0,
                    color: C.ash,
                  }}
                >
                  <Plus size={16} />
                  <input type="file" accept="image/*" multiple onChange={handleReferencias} style={{ display: "none" }} />
                </label>
              </div>
            </div>
          )}

          <div className="card" style={{ maxWidth: 520, marginTop: 24 }}>
            <div className="row">
              <div className="row-icon"><Edit3 size={16} /></div>
              <div className="row-content">
                <div className="row-label">Notas sobre estas referencias</div>
                <textarea
                  rows={3}
                  value={notasReferencias}
                  onChange={(e) => setNotasReferencias(e.target.value)}
                  placeholder="¿Qué sí quiere transmitir? ¿Qué no quiere imponer?"
                />
              </div>
            </div>
          </div>

          <div className="card" style={{ maxWidth: 520, marginTop: 20 }}>
            <div className="row">
              <div className="row-icon"><Eye size={16} /></div>
              <div className="row-content">
                <div className="row-label">¿Cómo te visualizas?</div>
                <textarea
                  rows={3}
                  value={visualizacion}
                  onChange={(e) => setVisualizacion(e.target.value)}
                  placeholder="Describe cómo te ves a ti misma"
                />
              </div>
            </div>
          </div>

          <div style={{ maxWidth: 520, marginTop: 28, display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 10 }}>
            <button
              onClick={handleGuardar}
              disabled={guardando}
              style={{
                background: C.black,
                color: C.ivory,
                border: "none",
                borderRadius: 999,
                padding: "14px 34px",
                fontSize: 15,
                fontFamily: "'Montserrat', sans-serif",
                fontWeight: 600,
                cursor: guardando ? "default" : "pointer",
                opacity: guardando ? 0.6 : 1,
              }}
            >
              {guardando ? "Guardando..." : "Guardar"}
            </button>
            {guardado && (
              <div style={{ width: "100%" }}>
                <span style={{ fontSize: 13, color: C.charcoal, display: "block", marginBottom: 8 }}>
                  Ficha guardada correctamente. Comparte este link con la clienta:
                </span>
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 8,
                    background: "#fff",
                    border: `1px solid ${C.stone}`,
                    borderRadius: 12,
                    padding: "10px 14px",
                  }}
                >
                  <span style={{ fontSize: 13, color: C.charcoal, wordBreak: "break-all", flex: 1 }}>
                    {linkFicha}
                  </span>
                  <button
                    onClick={copiarLink}
                    style={{
                      background: C.black,
                      color: C.ivory,
                      border: "none",
                      borderRadius: 999,
                      padding: "6px 14px",
                      fontSize: 12,
                      fontFamily: "'Montserrat', sans-serif",
                      cursor: "pointer",
                      whiteSpace: "nowrap",
                    }}
                  >
                    Copiar
                  </button>
                </div>
              </div>
            )}
            {errorGuardar && (
              <span style={{ fontSize: 13, color: "#B3261E" }}>{errorGuardar}</span>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

function navArrowStyle(side) {
  return {
    position: "absolute",
    top: "50%",
    [side]: 10,
    transform: "translateY(-50%)",
    background: "#fff",
    border: "none",
    borderRadius: "50%",
    width: 32,
    height: 32,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    cursor: "pointer",
    boxShadow: "0 2px 8px rgba(0,0,0,0.12)",
  };
}

function Pill({ active, onClick, children }) {
  return (
    <button
      onClick={onClick}
      style={{
        padding: "8px 20px",
        borderRadius: 999,
        border: `1px solid ${active ? C.black : C.stone}`,
        background: active ? C.black : "transparent",
        color: active ? C.ivory : C.charcoal,
        fontSize: 13,
        fontFamily: "\'Montserrat\', sans-serif",
        cursor: "pointer",
        transition: "all 0.15s ease",
      }}
    >
      {children}
    </button>
  );
}

function IconInput({ icon, children, align = "center", maxWidth }) {
  return (
    <div style={{ position: "relative", maxWidth: maxWidth || "none" }}>
      <div
        style={{
          position: "absolute",
          left: 16,
          top: align === "top" ? 16 : "50%",
          transform: align === "top" ? "none" : "translateY(-50%)",
          color: C.ash,
          pointerEvents: "none",
          zIndex: 1,
        }}
      >
        {icon}
      </div>
      {children}
    </div>
  );
}

function PhoneFrame({ image, onChange, onClear }) {
  return (
    <div
      style={{
        background: C.stone,
        borderRadius: 32,
        padding: 24,
        display: "flex",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          width: "100%",
          maxWidth: 220,
          aspectRatio: "9/18.5",
          background: "#fff",
          borderRadius: 22,
          border: `7px solid ${C.black}`,
          overflow: "hidden",
          position: "relative",
        }}
      >
        {image ? (
          <>
            <img src={image} alt="IG" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
            <button
              onClick={onClear}
              style={{
                position: "absolute",
                top: 10,
                right: 10,
                background: C.black,
                border: "none",
                borderRadius: "50%",
                width: 24,
                height: 24,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                cursor: "pointer",
              }}
            >
              <X size={13} color={C.ivory} />
            </button>
          </>
        ) : (
          <label
            style={{
              width: "100%",
              height: "100%",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              gap: 10,
              cursor: "pointer",
              color: C.ash,
              fontSize: 12.5,
              textAlign: "center",
              padding: 20,
            }}
          >
            <ImagePlus size={24} />
            Pantallazo de Instagram
            <input type="file" accept="image/*" onChange={onChange} style={{ display: "none" }} />
          </label>
        )}
      </div>
    </div>
  );
}
